DOCUMENT();
############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "contextCurrency.pl", "contextForm.pl", "parserGraphTool.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
$b = random(800,1000,100); $r = list_random(20,25,50); $f = Formula("$b + $r x"); Context("Currency"); $bc = Currency($b); $rc = Currency($r); $gt = GraphTool("{line,solid,(0,$b),(1,$b+$r)}")->with( bBox => [-2,1500,12,-100], availableTools => [ "LineTool" ], gridY => 100, ticksDistanceY => 200, snapSizeY => ($r == 20) ? 20 : 25, showCoordinateHints => 0, showInStatic => 0, xAxisLabel => 'x\\text{ (months)}', yAxisLabel => 'y\\text{ (dollars)}' );
###### # Body ######
BEGIN_PGML A new water heater for your home is will cost [`[$bc]`] to buy and have installed. With this new more efficient water heater, your monthly gas bill will be (on average) [`[$rc]\text{.}`] According to this information, the equation [`y=[$f]`] models the total expense from heating your domestic hot water after [`x`] months, where [`y`] is in dollars. Make a graph of this equation.
[_]{$gt}{1}
END_PGML
############# # End Problem #############
ENDDOCUMENT();
